$t=$ar?['title'=>'نموذج عقد كراء تجريبي','test'=>'للتجربة فقط - غير صالح للاستعمال الحقيقي','intro'=>'هاد النموذج كيجمع معلومات ملف الكراء لاختبار الطباعة والتوقيع. الشروط القانونية والتجارية وبيانات الوكالة النهائية مازال ما تعتمدو.','agency'=>'الوكالة','client'=>'الزبون','identity'=>'وثيقة الهوية','licence'=>'رخصة السياقة','expires'=>'نهاية صلاحية الرخصة','phone'=>'الهاتف','car'=>'السيارة','plate'=>'رقم التسجيل','period'=>'المدة المتفق عليها','start'=>'بداية الكراء','end'=>'نهاية الكراء','zone'=>'التواريخ بتوقيت المغرب','rent'=>'ثمن الكراء المتفق عليه','deposit'=>'الضمان - مستقل عن الكراء','waived'=>'إعفاء مسجل من الضمان','undefined'=>'غير محدد','inspection'=>'فحص ما قبل التسليم','km'=>'العداد بالكيلومتر','fuel'=>'مستوى الوقود','state'=>'الحالة والملاحظات','photos'=>'صور محفوظة في ملف الفحص','conditions'=>'الشروط النهائية مازال خاصها الاعتماد','terms'=>'ما تحددات هنا حتى غرامة جديدة أو اقتطاع من الضمان أو التزام قانوني. التوقيع أدناه للتجربة فقط.','customer_sign'=>'توقيع الزبون','agency_sign'=>'توقيع الوكالة','date'=>'التاريخ','ref'=>'مرجع النسخة','file'=>'ملف الكراء','page2'=>'ورقة مراجعة النسخة الموقعة','check'=>'راجع أن النسخة المرفوعة واضحة وكاملة وعندها نفس المرجع والتوقيعات. رفع الملف بوحدو ما كيعنيش التحقق منو.','notout'=>'هاد الوثيقة ما كتسجلش خروج السيارة.','good'=>'حالة جيدة مسجلة','damage'=>'أضرار أو خدوش سابقة مسجلة','blocked'=>'عطب يمنع الخروج']:['title'=>'Modèle de contrat de location','test'=>'SIMULATION - DOCUMENT NON VALABLE POUR UN USAGE RÉEL','intro'=>'Ce modèle reprend les informations du dossier pour tester l’impression et la copie signée. Les conditions contractuelles et les mentions finales de l’agence restent à valider.','agency'=>'Agence','client'=>'Client','identity'=>'Pièce d’identité','licence'=>'Permis de conduire','expires'=>'Expiration du permis','phone'=>'Téléphone','car'=>'Véhicule','plate'=>'Immatriculation','period'=>'Période convenue','start'=>'Départ prévu','end'=>'Retour prévu','zone'=>'Dates et heures du Maroc','rent'=>'Loyer